const move = (el, v) => el && el.setAttribute("transform", translateAlong(P, v));
const st = { u: -1, running: false, mode: 0, done: null, next: 0 };
let last = 0, frame = 0, visible = false, touring = !still.matches, idleClock = 0, idleTimer = 0, line = "";

const T = C.T;
const colony = $('[data-part="colony"] .iso-solid'), vials = $$("[data-vial]").map((g) => g.firstElementChild), lamps = $$("[data-lamp]").map((g) => g.firstElementChild);
